#![allow(unused_imports)]
use vstd::prelude::*;
use vstd::vec::Vec;

verus! {
    /// Given a non‐empty Vec of i32 and an index `n` with 0 < n < list.len(),
    /// returns a new Vec which is the original Vec rotated to the left by `n`.
    /// I.e. result = list[n..] ++ list[0..n].
    #[verifier(publish)]
    fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
        let len = list.len();
        // Pre‐conditions
        requires(len > 0);
        requires(n > 0 && n < len);

        // Post‐condition: the new Vec has the same length,
        // and for all i < len, new_list[i] = list[(n + i) % len].
        ensures(|new_list: &Vec<i32>| {
            new_list.len() == len
            &&
            forall(|i: usize| i < len ==>
                new_list[i] == list[(n + i) % len]
            )
        });

        let mut new_list = Vec::new();
        let mut i: usize = 0;

        // Build the rotated vector by pushing elements list[(n + i) % len]
        while i < len {
            // Invariants to help Verus track correctness:
            // 1) we've done i steps so far,
            // 2) new_list.len() == i,
            // 3) for all j < i, new_list[j] == list[(n + j) % len].
            invariant(i <= len);
            invariant(new_list.len() == i);
            invariant(forall(|j: usize| j < i ==>
                new_list[j] == list[(n + j) % len]
            ));
            decreases(len - i);

            let idx = (n + i) % len;
            new_list.push(list[idx]);
            i += 1;
        }

        new_list
    }
}